window.AAQ_ASSIGN = {"unit": 3, "title": "Engineering Design", "aims": [{"aim": "A", "title": "Explore initial design proposals to meet the requirements of an engineering design challenge"}, {"aim": "B", "title": "Develop initial design ideas into 3-dimensional models in response to an engineering design challenge"}, {"aim": "C", "title": "Develop 3-dimensional models into 2-dimensional engineering drawings and present the final design solution"}, {"aim": "D", "title": "Review the design process when responding to an engineering design challenge"}], "criteria": [{"code": "A.P1", "aims": "A", "grade": "P", "n": 1, "text": "Produce an adequate product design specification for the given engineering design challenge using some research and analysis."}, {"code": "A.P2", "aims": "A", "grade": "P", "n": 2, "text": "Produce adequate initial design ideas that address some requirements of the product design specification."}, {"code": "A.M1", "aims": "A", "grade": "M", "n": 1, "text": "Produce a mostly detailed product design specification for the given engineering design challenge using detailed research and analysis."}, {"code": "A.M2", "aims": "A", "grade": "M", "n": 2, "text": "Produce mostly detailed initial design ideas that address the most important requirements of the product design specification."}, {"code": "A.D1", "aims": "A", "grade": "D", "n": 1, "text": "Produce a detailed product design specification for the given engineering design challenge using comprehensive research and analysis."}, {"code": "A.D2", "aims": "A", "grade": "D", "n": 2, "text": "Produce detailed initial design ideas that address most of the requirements of the product design specification."}, {"code": "B.P3", "aims": "B", "grade": "P", "n": 3, "text": "Review the initial design ideas and use some peer feedback to clarify the features that address some of the requirements of the product design specification."}, {"code": "B.P4", "aims": "B", "grade": "P", "n": 4, "text": "Develop initial design ideas into adequate digital 3D models that address some requirements of the product design specification."}, {"code": "B.M3", "aims": "B", "grade": "M", "n": 3, "text": "Assess the initial design ideas and use peer feedback appropriately to clarify the features that address the most important requirements of the product design specification."}, {"code": "B.M4", "aims": "B", "grade": "M", "n": 4, "text": "Develop initial design ideas into detailed digital 3D models that address the most important requirements of the product design specification."}, {"code": "B.D3", "aims": "B", "grade": "D", "n": 3, "text": "Evaluate the initial design ideas and use peer feedback effectively to clarify the features that address most of the requirements of the product design specification"}, {"code": "B.D4", "aims": "B", "grade": "D", "n": 4, "text": "Develop initial design ideas into detailed digital 3D models that address most of the requirements of the product design specification."}, {"code": "C.P5", "aims": "C", "grade": "P", "n": 5, "text": "Develop 3- dimensional models into 2-dimensional engineering drawings to partially communicate a final design solution that meets some requirements of the product design specification, describing some decisions taken."}, {"code": "C.M5", "aims": "C", "grade": "M", "n": 5, "text": "Develop 3-dimensional models into detailed 2-dimensional engineering drawings to communicate a final design solution that meets the most important requirements of the product design specification, explaining the decisions taken."}, {"code": "C.D5", "aims": "C", "grade": "D", "n": 5, "text": "Develop 3- dimensional models into detailed 2-dimensional engineering drawings to fully communicate a final design solution that meets most of the requirements of the product design specification, justifying all decisions taken."}, {"code": "D.P6", "aims": "D", "grade": "P", "n": 6, "text": "Explain how the design process was used to produce a final design solution that meets some of the requirements of the product design specification."}, {"code": "D.M6", "aims": "D", "grade": "M", "n": 6, "text": "Assess how the design process was effectively used to produce a final design solution that meets the most important requirements of the product design specification."}, {"code": "D.D6", "aims": "D", "grade": "D", "n": 6, "text": "Evaluate how the design process was effectively used to produce a final design solution that meets most of the requirements of the product design specification."}], "guidance": [{"aims": "A", "paras": ["For distinction standard, students will collect and analyse a comprehensive range of primary data specific to the given engineering challenge. They will use this to refine most of the Product Design Specification (PDS) technical requirements related to user requirements, product function, form, quantity and interactions with other areas/components. For example, they will gather evidence from potential users of the product to determine their priorities for the functions the product performs. They will collect and analyse secondary data specific to their engineering challenge that allows them to refine most of the PDS content related to potential manufacturing methods and materials, costs, safety, maintenance and reliability, legal requirements and sustainability. For example, students will fully address how they can ensure their proposed product can be designed to be sustainable. They will use their analysis of the information to support the writing of a PDS that defines the technical requirements expected from their final design solution. They will justify most of the PDS points with reference to relevant data. Their solution to the PDS will require them to demonstrate knowledge and understanding of materials and manufacturing processes, for example that Polylactic acid (PLA) is commonly used in Fused Deposition Modelling (FDM). The PDS will support the objective evaluation of their final design solution against most of the demands of the engineering challenge. They will produce annotated 2D and 3D sketches by freehand or using assistive technologies, in good proportion, that are detailed, technically correct and clearly convey their design intentions to a third party. For example, they will sketch linked views in an orthographic drawing that indicates the potential sizes of a component. They will produce physical models that help to convey their design intentions. Most of the requirements of the PDS will be addressed by one, or more, of these types of evidence.", "They will demonstrate comprehensive analysis skills by producing written comparisons of most of their initial design ideas against the requirements of the PDS. For example, how manufacturing the product from aluminium will ease recycling, at the end of the product life cycle. Their initial design ideas will demonstrate significantly different approaches to resolving the design challenge. For example, they will suggest machining components to form an assembly or 3D printing a single component to achieve the same outcome. Most of their design ideas, other than those they identify as not being appropriate, will be feasible and offer effective solutions for the PDS for the engineering challenge. For merit standard, students will collect and analyse appropriate and detailed primary data specific to the given engineering challenge. They will use this to refine the most important of the Product Design Specification (PDS) technical requirements content related to user requirements, product function, form, quantity and interactions with other areas/components. For example, they will gather photographic evidence of the environment the product will operate in. They will collect and analyse secondary data specific to their engineering challenge that allows them to refine the most important PDS content related to potential manufacturing methods and materials, costs, safety, maintenance and reliability, legal requirements and sustainability. For example, students will determine if similar products are protected as intellectual property. They will use their analysis of the information to support the writing of a PDS that defines the technical requirements expected from their final design solution. They will give a well- reasoned explanation of the most important PDS points with some reference to data. Their solution to the PDS will require them to demonstrate knowledge and understanding of materials and manufacturing processes, for example that fabricating steel allows complex structures to be formed. The PDS will support the objective evaluation of their final design solution against the most important demands of the engineering challenge. They will produce annotated 2D and 3D sketches by freehand or using assistive technologies, in good proportion, that are mostly technically correct and clearly convey their design intentions to a third party. For example, they will sketch single views in an orthographic drawing that indicates the potential sizes of a component. They will produce physical models that help to convey their design intentions. The most important requirements of the PDS will be addressed by one, or more, of these types of evidence. They will demonstrate good analysis skills by producing written comparisons of most of their initial design ideas against the requirements of the PDS. For example, how one design solution would be simpler to manufacture than another. Their initial design ideas will demonstrate some different approaches to resolving the design challenge. For example, they will suggest a component made from polymer vacuum formed or line bent. Most of their design ideas, other than those they identify as not being appropriate, will be feasible and offer solutions for the PDS for the engineering challenge.", "For pass standard, students will collect and analyse appropriate primary data specific to the given engineering challenge. They will use this to refine some of the Product Design Specification (PDS) technical requirements content related to user requirements, product function, form, quantity and interactions with other areas/components. For example, they will determine the maximum and minimum possible dimensions for their product. They will collect and analyse secondary data specific to their engineering challenge that allows them to refine some of the PDS content related to potential manufacturing methods and materials, costs, safety, maintenance and reliability, legal requirements and sustainability. For example, students will use supplier catalogues to determine the range, and associated costs, of materials that may be appropriate to consider for the manufacture of the product. They will use their analysis of the information to support the writing of a PDS that defines the technical requirements expected from their final design solution. They will describe most of the PDS points. Their solution to the PDS will require them to demonstrate knowledge and understanding of materials and manufacturing processes, for example that acrylic can be thermoformed. The PDS will support the objective evaluation of their final design solution against demands of the engineering challenge. Their PDS will contain sufficient detail to allow them to make a reasoned decision if their final design solution is fit for purpose. They will produce annotated 2D and 3D sketches by freehand or using assistive technologies, in good proportion, that clearly convey their design intentions to a third party. For example, produce an isometric drawing of a component that forms part of an assembly. For example, they will sketch an isometric drawing of a component. They will produce physical models that help to convey their design intentions. They will demonstrate good analysis skills by producing written comparisons of some their initial design ideas against the requirements of the PDS. For example how one design idea would look more appealing than another. Some of the requirements of the PDS will be addressed by one, or more, of these types of evidence. Their initial design ideas will demonstrate some variation in approaches to resolving the design challenge. For example, they will suggest a component made from steel could be produced by bending or welding. Some of their design ideas, other than those they identify as not being appropriate, will be feasible and offer solutions for the PDS for the engineering challenge."]}, {"aims": "B", "paras": ["For distinction standard, students will objectively review most of their initial design ideas against their PDS, justifying both positive and negative features they identify. For example, they will accurately calculate the cost of the materials required to manufacture a design idea and compare this to the relevant PDS requirement.", "They will effectively use peer feedback and their own review, to justify why an initial idea, or combined elements of initial ideas, has been chosen to develop. For example, they will indicate that while one of their design ideas has the most positive features the same idea has a negative feature that would have a bigger influence on the success of the final product. Their responses will be logically structured and will use correct technical engineering terms with a high standard of written language, i.e. consistent use of correct grammar and spelling. Students will produce digital 3D models of components that will form an assembly that fully meets the requirements of the engineering challenge, as detailed by the PDS. The digital 3D models will demonstrate an iterative approach to the design process, where the features that affect the form and function of components have been investigated. For example, students will reduce the thickness of a component to improve its aesthetics while retaining its functionality. All components of the complete final design solution will be rendered in 3D to show a realistic product design. Students will justify their choice of materials and manufacturing processes, taking into account form and function that would be appropriate to manufacture the product. For example, they will indicate that anodising aluminium will improve its physical properties and can alter its colour. Students will produce a ‘portfolio’ of images of rendered digital 3D models that show most features of the final design solution. For example, they will include different images to show an overview and zoomed in details of a component. The format of the portfolio, for example a video recording, will be appropriate for the content they have produced. The portfolio will be logically structured and clearly present the information to a third party. For merit standard, students will objectively review most of their initial design ideas against their PDS explaining both positive and negative features that they identify. For example, they will consider how features of their design ideas impact on the requirements of the user and compare this to the relevant PDS requirement. They will use peer feedback, and their own review, to explain why an initial idea, or combined elements of initial ideas, has been chosen to develop. For example, they will indicate that a potential user of the product has expressed a preference. Their responses will be logically structured, technically accurate and easy to understand. Students will produce digital 3D models of components that will form an assembly that mostly meets the requirements of the engineering challenge, as detailed by the PDS. The digital 3D models will demonstrate an iterative approach to the design process, where the features that affect the function of components have been investigated. For example, students will amend the sizes of components so that they will improve the way they fit together.", "Most components of the complete final design solution will be rendered in 3D to show a realistic product design. Students will explain their reasons for their choice of materials and manufacturing processes, taking into account form that would be appropriate to manufacture the product. For example, they will indicate sand casting aluminium has a low set-up cost suitable for manufacturing small numbers of products. Students will produce a ‘portfolio’ of images of 3D models that mostly meet their purpose, for example to display visualisation to a potential customer, and are mostly clear for a third party to understand. The format of the portfolio, for example a software presentation, will be appropriate for the content they have produced. The portfolio will clearly present the information to a third party, but may lack organisation. For pass standard, students will objectively review their initial design ideas against their PDS describing both positive and negative features they identify. For example, they will consider how features of their design ideas impact on the relevant PDS requirement. They will use some peer feedback and their own review, to describe why elements of initial ideas have been chosen to develop. For example, they indicate why one of their design ideas will be simpler to manufacture. Their responses may be basic in parts and may have some inaccuracies relating to engineering terminology. Students will produce digital 3D models of components that will form an assembly that meets some of the requirements of the engineering challenge, as detailed by the PDS. The digital 3D models will demonstrate an iterative approach to the design process, where the form of components has been investigated. For example, students will introduce curves to surface. Some components of the complete final design solution will be rendered in 3D to show a realistic product design. Students will explain their reasons for their choice of materials or manufacturing processes, taking into account form that would be appropriate to manufacture the product. For example, they will indicate that bonding a component will result in a better appearance than welding it. Students should produce a ‘portfolio’ of images of 3D models that meet some of their purpose, for example to display visualisation to a potential customer, and present some clear information for a third party to understand. The format of the portfolio, for example a document, will be appropriate for the content they have produced and will present the information to a third party, but may require interpretation."]}, {"aims": "C", "paras": ["For distinction standard, students will use their digital 3D models developed for LA B to produce CAD orthographic drawings. These orthographic drawings may be produced manually, or by software conversion direct from the digital 3D model, or by combination of the two methods. The final digital 3D models of the solution developed for LA B will have an associated orthographic drawing produced. All of the drawings produced will show evidence that they have prepared and used additional layers, as required by the model. For example, separate layers, with different properties, for views of the product, the drawing template, dimensions and one for annotation, will be set up. The drawings will provide most of the information needed to allow the complete final design solution to be manufactured. For example, they will be fully dimensioned with materials specified. Overall, most details in the orthographic drawings will be produced to typically represent the standards found in BS 8888 (or other relevant standards), with very few omissions or errors evident. Students will produce a ‘portfolio’ of their orthographic drawings, for example, a document that contains all the content they have produced. The portfolio will be logically structured and clearly present the information to a third party. They will produce a report, in a format of their choice (either written or through preparation and delivery of a presentation), that describes most of the stages they have completed to produce their final design solution. The report will justify the decisions they made to arrive at their final design solution. For example, they will record why some of the initial ideas were rejected. If students choose to prepare and deliver presentation of their report outcomes for an audience, for example their peers, the presentation should be recorded in a format that allows the content to be reviewed afterwards, for example an audio-video recording, transcript of the presentation, or a student produced script for the presentation. When preparing the report, students will select the information they present from the evidence they have produced for all of the following elements of the Pearson-set Assignment Brief. • the research they conducted. • the PDS • their initial design ideas • why they selected an initial design idea to develop • their digital 3D models • their orthographic drawings • the materials and processes that would be used to manufacture the product. The report or presentation will be completed to a high standard that is logical, clear and consistent, and will be easily understood by non-engineers.", "For merit standard, students will use their digital 3D models developed for LA B to produce CAD orthographic drawings. These orthographic drawings may be produced manually, or by software conversion direct from the digital 3D model, or by combination of the two methods. The final digital 3D models of the solution developed for LA B will have associated orthographic drawings produced. Most of the drawings produced will show evidence that they have prepared and used additional layers, as required by the model. For example, separate layers for views of the product, the drawing template, dimensions and one for annotation, will be set up. The drawings will provide the most important features of the information needed to allow the complete final design solution to be manufactured. There may be some minor omissions, for example, some dimensions will not be specified. Overall, most of the details in the orthographic drawings will be produced to typically represent the standards found in BS 8888 (or other relevant standards), although there may be some minor errors evident, such as the lack of a visible gap between some features of the component and extension lines, or some text that is incorrectly orientated. Students will produce a ‘portfolio’ of their orthographic drawings, for example, software presentation that contains all the content they have produced. The portfolio will clearly present the information to a third party but may lack organisation. They will produce a report, in a format of their choice (either written or through preparation and delivery of a presentation), that describes the most important stages they have completed to produce their final design solution. The report will explain the decisions they made to arrive at their final design solution. For example, they will record why the materials specified were selected. If students choose to prepare and deliver presentation of their report outcomes for an audience, for example their peers, the presentation should be recorded in a format that allows the content to be reviewed afterwards, for example an audio-video recording, transcript of the presentation, or a student produced script for the presentation. When preparing the report, students will select the information they present from the evidence that have produced for all of the following elements of the Pearson-set Assignment Brief. • the PDS • their initial design ideas • why they selected an initial design idea to develop • their digital 3D models • their orthographic drawings The report or presentation will be completed consistently, in a clear and mostly logical way, to be understood by non-engineers.", "For pass standard, students will use their digital 3D models developed for LA B to produce CAD orthographic drawings. These orthographic drawings may be produced manually, or by software conversion direct from the digital 3D model, or by combination of the two methods. Most of the final 3D digital models developed for LA B will have associated orthographic drawings produced. Some of the drawings will show evidence that they have prepared and used additional layers. For example, separate layers for views of the product and dimensions will be set up. The drawings will provide some of the information needed to allow some components of the final design solution to be manufactured. There may be some minor omissions, for example some dimensions will not be specified. Overall, most details in the orthographic drawings must be suitable for a competent third party to manufacture the component. Students will produce a ‘portfolio’ of their orthographic drawings that contains all the content they have produced. The portfolio will present the information to a third party, but may require interpretation. They will produce a report, in a format of their choice (either written or through preparation and delivery of a presentation), that describes some of the stages they have completed to produce their final design solution. The report will describe the decisions they made to arrive at their final design solution. For example, they will record why they chose their initial idea to develop. If students choose to prepare and deliver presentation of their report outcomes for an audience, for example their peers, the presentation should be recorded in a format that allows the content to be reviewed afterwards, for example an audio-video recording, transcript of the presentation, or a student produced script for the presentation. When preparing the report, students will select the information they present from the evidence that have produced for all of the following elements of the Pearson-set Assignment Brief. • the PDS • their initial design ideas • their digital 3D models • their orthographic drawings The report or presentation will be completed to a satisfactory standard but may have some parts that would be inaccurate or unclear."]}, {"aims": "D", "paras": ["For distinction standard, students will compare their final design solution against most of the elements of their PDS. They will evaluate the extent to which they have satisfied the engineering challenge and provided an effective solution. For example, they will compare the costs they have calculated to manufacture the functions stated in the PDS. They will identify at least three changes that could be made to their final design solution. They will then explain how these will result in improvements. For example, they may identify an alternative manufacturing process that could produce greater accuracy than the existing suggestion. All three of the changes suggested will be feasible. Students will review how the way they worked during the production of the PDS, initial sketches, 3D models and orthographic drawings supported the success of their final design solution. They should reference a number of specific aspects in their review, i.e. how well they stayed on task and their ability to work independently, how well they demonstrated this. Students will identify at least three ways in which their performance in the specific areas they have identified could be improved, i.e. how well they stayed on task and their ability to work independently, how well they demonstrated this. They will explain how these changes would have affected the final design solution and the presentation of the outcomes, and how their performance in the specific areas they have identified could be improved. Students will review how effective their report (written or presentation) was in communicating their final design solution. Overall, their submissions will be easy to read and understood by a third party, who may or may not be an engineer. They will be logically structured and use correct technical engineering terms. Students’ language will be of a high standard, for example they will use correct grammar. For merit standard, students will compare their final design solution against the most important elements of their PDS. They will assess the extent to which they have satisfied the engineering challenge and provided an effective solution. For example, they will consider how effectively they expect the product to function against the requirements stated in the PDS. They will identify at least two changes that could be made to their final design solution. They will then explain how these changes will result in improvements. For example, they may identify how they could reduce the overall size of their product while still maintaining functionality. At least one of the changes will be feasible, and the other mostly feasible. Students will review how the way they worked during the production of at least three of the PDS, initial sketches, 3D models and orthographic drawing stages supported the success of their final design solutions. They should reference a couple of specific aspects in their review, i.e. how well they stayed on task and their ability to work independently, how well they demonstrated this.", "Students will identify at least two ways in which their performance in the specific areas they have identified could be improved, explaining how these changes would have affected the final design solution. Students will review how effective their report (written or presentation) was in communicating their design solution. Overall, their submissions will be easy to read and understood by a third party, who may or may not be an engineer. They will be logically structured, but may use some incorrect technical engineering terms. For pass standard, students will compare their final design solution against some of the elements of their PDS. They will explain the extent to which they have satisfied the engineering challenge. For example, they will describe how features of their final design solution compare to those stated in the PDS. They will identify a change that could be made to their final design solution. They will then explain how the change will result in improvement. For example, they identify that a change in the product’s appearance will mean it will be more harmonious with the environment it will function in. The change will be mostly feasible. Students will review how the way they worked during the production of at least one of the PDS, initial sketches, 3D models and orthographic drawing stages supported the success of their final design solution. They should reference a couple of specific aspects in their review, i.e. how well they stayed on task and their ability to work independently, how well they demonstrated this. Students will identify at least one way in which their performance in the specific areas they have identified could be improved, explaining how these changes would have affected the final design solution. Students will review how effective their report (written or presentation) was in communicating their design solution. Overall, their submission will be logically structured, although basic in parts."]}]};
